import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.List;
import java.util.Queue;

public class Main {
    static final int[][] DIRS = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        List<String> lines = new ArrayList<>();
        String line;
        while ((line = br.readLine()) != null) {
            if (line.isBlank()) {
                continue;
            }
            lines.add(line.strip());
        }
        char[][] grid = new char[lines.size()][];
        for (int r = 0; r < grid.length; r++) {
            grid[r] = lines.get(r).toCharArray();
        }

        System.out.println("Minutes: " + minutesToBurn(grid));
    }

    static int minutesToBurn(char[][] grid) {
        int rows = grid.length;
        int cols = grid[0].length;
        Queue<int[]> queue = new ArrayDeque<>();
        int grass = 0;
        for (int r = 0; r < rows; r++) {
            for (int c = 0; c < cols; c++) {
                if (grid[r][c] == 'F') {
                    queue.offer(new int[]{r, c});
                } else if (grid[r][c] == '.') {
                    grass++;
                }
            }
        }

        int minutes = 0;
        while (!queue.isEmpty() && grass > 0) {
            int size = queue.size();
            for (int i = 0; i < size; i++) {
                int[] cur = queue.poll();
                for (int[] d : DIRS) {
                    int nr = cur[0] + d[0];
                    int nc = cur[1] + d[1];
                    if (nr < 0 || nr >= rows || nc < 0 || nc >= cols) {
                        continue;
                    }
                    if (grid[nr][nc] != '.') {
                        continue;
                    }
                    grid[nr][nc] = 'F';
                    grass--;
                    queue.offer(new int[]{nr, nc});
                }
            }
            minutes++;
            System.out.println("After minute " + minutes + ": " + grass + " left");
        }
        return grass == 0 ? minutes : -1;
    }
}

